class LFUCache:
    def __init__(self, capacity):
        self.cap, self.time = capacity, 0
        self.data = {}                                 # key -> [value, count, last_used]

    def get(self, key):
        if key not in self.data:
            return -1
        self.time += 1
        entry = self.data[key]
        entry[1] += 1
        entry[2] = self.time
        return entry[0]

    def put(self, key, value):
        if self.cap == 0:
            return
        self.time += 1
        if key in self.data:
            e = self.data[key]
            e[0], e[1], e[2] = value, e[1] + 1, self.time
            return
        if len(self.data) == self.cap:
            victim = min(self.data, key=lambda k: (self.data[k][1], self.data[k][2]))
            del self.data[victim]
        self.data[key] = [value, 1, self.time]

class LFUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.vals, self.freq = {}, {}
        self.buckets = defaultdict(OrderedDict)        # freq -> keys, oldest first
        self.min_freq = 0

    def _touch(self, key):
        f = self.freq[key]
        del self.buckets[f][key]
        if not self.buckets[f]:
            del self.buckets[f]
            if self.min_freq == f:
                self.min_freq = f + 1
        self.freq[key] = f + 1
        self.buckets[f + 1][key] = None

    def get(self, key):
        if key not in self.vals:
            return -1
        self._touch(key)
        return self.vals[key]

    def put(self, key, value):
        if self.cap == 0:
            return
        if key in self.vals:
            self.vals[key] = value
            self._touch(key)
            return
        if len(self.vals) == self.cap:
            victim, _ = self.buckets[self.min_freq].popitem(last=False)
            if not self.buckets[self.min_freq]:
                del self.buckets[self.min_freq]
            del self.vals[victim], self.freq[victim]
        self.vals[key], self.freq[key] = value, 1
        self.buckets[1][key] = None
        self.min_freq = 1
